INSERT INTO comment_write_outbox (
    comment_id, post_id, root_id, parent_id, creator_id, client_request_id, body,
    state, attempt_count, next_attempt_at, created_at, updated_at
) VALUES (
    #{commentId}, #{postId}, #{rootId}, #{parentId}, #{creatorId}, #{clientRequestId}, #{body},
    'pending', 0, #{nextAttemptAt}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE comment_write_outbox
SET state = 'publishing',
    claim_token = #{claimToken},
    claim_until = #{claimUntil},
    updated_at = #{now}
WHERE state = 'pending'
  AND next_attempt_at <= #{now}
ORDER BY next_attempt_at, comment_id
LIMIT #{limit}

UPDATE comment_write_outbox
SET state = 'published',
    published_at = #{publishedAt},
    claim_token = NULL,
    claim_until = NULL,
    last_error = NULL,
    updated_at = #{publishedAt}
WHERE comment_id = #{commentId}
  AND state = 'publishing'
  AND claim_token = #{claimToken}
